import {RECORDS,RECORD_GENRES} from './records.js';
import {covers,gramophone,starIcon} from './vitrola-assets.js';
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stars='<span class="vitrola-stars" aria-hidden="true">'+starIcon+'</span>';
export function recordsMarkup(s,filter='TODOS',previewId=null){
 const active=s.records.active,now=RECORDS.find(r=>r.id===active)||RECORDS[0],shown=RECORDS.filter(r=>filter==='TODOS'||filter==='OWNED'&&s.records.owned.includes(r.id)||r.genre===filter),fmt=n=>new Intl.NumberFormat('pt-BR').format(n);
 return `<section class="r2-records"><div class="records-head"><div class="gramophone-scene" aria-hidden="true"><img src="${esc(gramophone)}" alt="" draggable="false"></div><div class="record-now"><h2>VITROLA</h2><p>Colete discos e escolha a trilha sonora das suas explorações.</p><span id="currentRecordTitle" tabindex="-1">Nas expedições · ${esc(now.name)}</span></div><div class="record-balance"><span>ESTRELAS</span><strong>${stars} ${fmt(s.stars)}</strong></div></div><nav class="record-filters record-collection-filters" aria-label="Filtrar coleção"><button type="button" data-record-filter="TODOS" class="${filter==='TODOS'?'selected':''}" aria-pressed="${filter==='TODOS'}">TODOS</button><button type="button" data-record-filter="OWNED" class="${filter==='OWNED'?'selected':''}" aria-pressed="${filter==='OWNED'}">NA COLEÇÃO · ${s.records.owned.length}</button></nav><details class="record-genre-filter" ${!['TODOS','OWNED'].includes(filter)?'open':''}><summary>GÊNEROS${!['TODOS','OWNED'].includes(filter)?' · '+esc(filter):''}</summary><nav class="record-filters" aria-label="Filtrar gêneros">${RECORD_GENRES.filter(g=>g!=='TODOS').map(g=>`<button type="button" data-record-filter="${esc(g)}" class="${filter===g?'selected':''}" aria-pressed="${filter===g}">${esc(g)}</button>`).join('')}</nav></details><div class="record-grid" aria-label="Coleção de discos">${shown.map(r=>{
 const owned=s.records.owned.includes(r.id),playing=active===r.id,previewing=previewId===r.id,blocked=!owned&&s.stars<r.cost;
 return `<article class="record-card ${playing?'playing':''} ${previewing?'previewing':''}" style="--record:${r.color}" data-record-card="${esc(r.id)}"><div class="record-cover" aria-hidden="true">${covers[r.id]?`<img src="${esc(covers[r.id])}" alt="" draggable="false">`:'<span class="cover-pending">Capa em produção</span>'}</div><div class="record-copy"><small>${esc(r.genre)}</small><h3 data-record-title="${esc(r.id)}" tabindex="-1">${esc(r.name)}</h3><span>${esc(owned?'NA COLEÇÃO':'ORIGEM · '+r.source)}</span></div><div class="record-actions"><button type="button" class="record-preview" data-record-preview="${esc(r.id)}" aria-pressed="${previewing}" aria-label="${esc((previewing?'Parar prévia':'Ouvir 5 segundos de')+' '+r.name)}">${previewing?'■ PARAR':'▶ OUVIR 5s'}<i class="record-preview-meter" aria-hidden="true"></i></button><button type="button" class="record-action primary" data-record="${esc(r.id)}" ${playing||blocked?'disabled':''}${blocked?' title="Estrelas insuficientes"':''}>${playing?'TOCANDO':owned?'TOCAR':`<span>COMPRAR</span><strong>${stars} ${fmt(r.cost)}</strong>`}</button></div></article>`;
 }).join('')}${shown.length?'':'<p class="record-empty">Nenhum disco neste gênero.</p>'}</div><footer class="vitrola-collection"><strong>Coleção <b>${s.records.owned.length} / ${RECORDS.length}</b></strong><progress value="${s.records.owned.length}" max="${RECORDS.length}" aria-label="Discos na coleção">${s.records.owned.length} / ${RECORDS.length}</progress></footer></section>`;
}
